// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health/live", wrapper.HealthLive)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health/ready", wrapper.HealthReady)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/applications", wrapper.ListApplications)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/applications", wrapper.CreateApplication)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/applications/{application}", wrapper.UnregisterApplication)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/applications/{application}", wrapper.GetApplication)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/applications/{application}", wrapper.UpdateApplication)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/applications/{application}:start", wrapper.StartApplication)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/applications/{application}:register", wrapper.RegisterApplication)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/applications/{application}:stop", wrapper.StopApplication)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/applications/{application}:sync", wrapper.SyncApplication)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/applications/{application}:rebuild", wrapper.RebuildApplication)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/applications/{application}:purge", wrapper.PurgeApplication)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/applications/{application}/configuration", wrapper.GetConfiguration)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/applications/{application}/configuration", wrapper.UpdateConfiguration)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/operations/{operation}", wrapper.GetOperation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/operations/{operation}:watch", wrapper.WatchOperation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/applications/{application}/logEntries", wrapper.ListLogEntries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/applications/{application}/logEntries:watch", wrapper.WatchLogEntries)

	return m
}

